CREATE DATABASE PROJETO_INTEGRADO; /* cria o banco de dados PROJETO_INTEGRADO */
USE PROJETO_INTEGRADO;

/* cria a tabela CLINICAS */
CREATE TABLE CLINICAS (
    ID_CLINICA INTEGER PRIMARY KEY,
    NOME VARCHAR(100)
);


/* cria a tabela FUNCIONARIOS */
CREATE TABLE FUNCIONARIOS (
    MATRICULA INTEGER PRIMARY KEY,
    NOME VARCHAR(100)
);


/* cria a tabela MEDICOS */
CREATE TABLE MEDICOS (
    CRM INTEGER PRIMARY KEY,
    NOME VARCHAR(100)
);


/* cria a tabela EXAME */
CREATE TABLE EXAME (
    PROTOCOLO INTEGER PRIMARY KEY,
    CARTAO_SUS BIGINT(15),
    NOME_PACIENTE VARCHAR(100),
    PROCEDIMENTO VARCHAR(100),
    REGIAO VARCHAR(100),
    DATA_AGENDAMENTO DATE,
    FK_MEDICO_CRM INTEGER,
    FK_FUNCIONARIO_MATRICULA INTEGER,
    FK_ID_CLINICA INTEGER,
    STATUS_AGENDAMENTO VARCHAR(20),
    

	/* adiciona chave estrangeira que identifica a clinica*/
    CONSTRAINT FK_EXAME_CLINICA
        FOREIGN KEY (FK_ID_CLINICA)
        REFERENCES CLINICAS (ID_CLINICA)
        ON DELETE RESTRICT,
	
    /* adiciona chave estrangeira que identifica o funcionário */
    CONSTRAINT FK_EXAME_FUNCIONARIO
        FOREIGN KEY (FK_FUNCIONARIO_MATRICULA)
        REFERENCES FUNCIONARIOS (MATRICULA)
        ON DELETE RESTRICT,

	/* adiciona chave estrangeira que identifica o médico */
    CONSTRAINT FK_EXAME_MEDICO
        FOREIGN KEY (FK_MEDICO_CRM)
        REFERENCES MEDICOS (CRM)
        ON DELETE RESTRICT
);

/* insere dados das clinicas na tabela CLINICAS */

